using System.Text.Json;
using Respiro.Core;
internal static class DockerDeepTests
{
    static void Assert(bool value,string message="Resultado inesperado"){if(!value)throw new Exception(message);}
    static DockerDeepReport Usage(string json){using var doc=JsonDocument.Parse(json);var r=new DockerDeepReport();DockerDeepDiagnostic.ParseUsage(doc.RootElement,r);return r;}
    static RecoveryReport Report(long bytes=100){var r=new RecoveryReport{Finished=DateTime.Now};r.Groups.Add(new(){Scope=new(@"C:\fixture\volume","Volume",RecoveryClass.Protected,"Dados","Risco","Revisar"),PhysicalBytes=bytes});return r;}
    static string Sample(RecoveryReport r,DateTimeOffset at,long bytes,bool complete=true)=>JsonSerializer.Serialize(new StorageAlertEvaluator.Sample(at.UtcDateTime,r.Groups[0].Path,RecoveryHistory.GroupHash(r,r.Groups[0]),bytes,complete))+"\n";
    public static void Register(List<(string,Action)> tests)
    {
        void Test(string name,Action test)=>tests.Add(("M7: "+name,test));
        Test("cache interno não equivale a economia NTFS",()=>{var r=Usage("{\"Images\":[],\"Volumes\":[],\"BuildCache\":[{\"ID\":\"a\",\"Size\":100,\"InUse\":false,\"Shared\":false}]}");Assert(r.GuestUnusedBuildCacheBytes==100&&r.HostRecoverableConfirmedBytes==0&&r.GuestFreeBytes==null&&!r.RealOperationExecuted);});
        Test("volume sem referências permanece persistente",()=>{var r=Usage("{\"Images\":[],\"BuildCache\":[],\"Volumes\":[{\"Name\":\"postgres_data\",\"UsageData\":{\"Size\":500,\"RefCount\":0}}]}");Assert(r.Resources.Single().Classification=="Dados persistentes protegidos"&&r.GuestUnusedBuildCacheBytes==0);});
        Test("cache ativo ou compartilhado não entra no potencial",()=>{var r=Usage("{\"BuildCache\":[{\"ID\":\"a\",\"Size\":100,\"InUse\":true,\"Shared\":false},{\"ID\":\"b\",\"Size\":200,\"InUse\":false,\"Shared\":true}]}");Assert(r.GuestUnusedBuildCacheBytes==0&&!r.InventoryComplete);});
        Test("cache sem estado não vira candidato",()=>{var r=Usage("{\"BuildCache\":[{\"ID\":\"a\",\"Size\":100}]}");Assert(r.GuestUnusedBuildCacheBytes==0&&r.Resources.Single().Classification.Contains("inconclusivo"));});
        Test("cache ausente não é zero medido",()=>{Assert(Usage("{}").GuestUnusedBuildCacheBytes==null);Assert(!Usage("null").InventoryComplete);});
        Test("IDs duplicados não duplicam cache",()=>{var r=Usage("{\"BuildCache\":[{\"ID\":\"a\",\"Size\":100,\"InUse\":false,\"Shared\":false},{\"ID\":\"a\",\"Size\":100,\"InUse\":false,\"Shared\":false}]}");Assert(r.GuestUnusedBuildCacheBytes==100);});
        Test("tamanho inválido não entra na soma",()=>{var r=Usage("{\"BuildCache\":[{\"ID\":\"a\",\"Size\":\"100\",\"InUse\":false,\"Shared\":false},{\"ID\":\"b\",\"Size\":-1,\"InUse\":false,\"Shared\":false}]}");Assert(r.GuestUnusedBuildCacheBytes==0);});
        Test("overflow de cache não produz tamanho negativo",()=>{var r=Usage("{\"BuildCache\":[{\"ID\":\"a\",\"Size\":9223372036854775807,\"InUse\":false,\"Shared\":false},{\"ID\":\"b\",\"Size\":10,\"InUse\":false,\"Shared\":false}]}");Assert(r.GuestUnusedBuildCacheBytes==long.MaxValue);});
        Test("container parado preserva camada gravável e dependências",()=>{var r=new DockerDeepReport();using var d=JsonDocument.Parse("[{\"Id\":\"a\",\"Names\":[\"laravel-db\"],\"Image\":\"postgres:17\",\"State\":\"exited\",\"SizeRw\":20,\"Mounts\":[{\"Type\":\"volume\",\"Name\":\"db\",\"Destination\":\"/var/lib/postgresql/data\"}]}]");DockerDeepDiagnostic.ParseContainers(d.RootElement,r);Assert(r.Resources.Single().Classification.Contains("importante")&&r.Resources[0].Dependencies.Contains("db")&&r.Resources[0].Reason.Contains("PostgreSQL")&&r.HostRecoverableConfirmedBytes==0);});
        Test("Env comandos e labels arbitrárias não são exportados",()=>{var r=new DockerDeepReport();using var d=JsonDocument.Parse("[{\"Id\":\"a\",\"Image\":\"redis:7\",\"State\":\"running\",\"Command\":\"SECRET_COMMAND\",\"Env\":[\"SECRET_ENV\"],\"Labels\":{\"password\":\"SECRET_LABEL\",\"com.docker.compose.project\":\"laravel\",\"com.docker.compose.service\":\"redis\"}}]");DockerDeepDiagnostic.ParseContainers(d.RootElement,r);var text=JsonSerializer.Serialize(r);Assert(!text.Contains("SECRET_")&&r.Resources[0].Dependencies.Contains("laravel")&&r.Resources[0].Classification=="Recurso ativo");});
        Test("inventário limita registros e declara parcial",()=>{var rows=Enumerable.Range(0,501).Select(i=>new{Id=i.ToString(),Size=10,Containers=0});var r=Usage(JsonSerializer.Serialize(new{Images=rows,Volumes=Array.Empty<object>(),BuildCache=Array.Empty<object>()}));Assert(r.Resources.Count==500&&!r.InventoryComplete);});
        Test("imagens sem containers são possibilidades e não autorização",()=>{var r=Usage("{\"Images\":[{\"Id\":\"a\",\"Containers\":0,\"Size\":100,\"SharedSize\":90,\"RepoTags\":[\"php:8\"]}]}");Assert(r.Resources[0].Classification=="Possivelmente não utilizada"&&r.HostRecoverableConfirmedBytes==0);});
        Test("API usa exclusivamente três GETs de diagnóstico",()=>{var routes=new List<string>();var r=new DockerDeepReport();DockerDeepDiagnostic.ReadEngine(r,(path,token)=>{routes.Add(path);return Task.FromResult(JsonDocument.Parse(path=="/version"?"{\"ApiVersion\":\"1.48\"}":path=="/system/df"?"{\"Images\":[],\"Volumes\":[],\"BuildCache\":[]}":"[]"));},default).GetAwaiter().GetResult();Assert(routes.SequenceEqual(LocalDockerReadApi.Routes)&&r.DaemonAvailable&&r.InventoryComplete);});
        Test("rota destrutiva e pipe configurável são rejeitadas",()=>{bool denied=false;try{using var bad=new LocalDockerReadApi("remote");}catch(ArgumentException){denied=true;}Assert(denied);using var api=new LocalDockerReadApi("docker_engine");try{api.Get("/system/prune",default).GetAwaiter().GetResult();throw new Exception("Rota aceita");}catch(InvalidOperationException){}});
        Test("cancelamento da API preserva ausência de operação",()=>{var r=new DockerDeepReport();using var cts=new CancellationTokenSource();cts.Cancel();try{DockerDeepDiagnostic.ReadEngine(r,(_,ct)=>Task.FromCanceled<JsonDocument>(ct),cts.Token).GetAwaiter().GetResult();throw new Exception("Cancelamento ignorado");}catch(OperationCanceledException){}Assert(!r.RealOperationExecuted&&!r.DaemonAvailable);});
        Test("WSL mescla nomes estados e preserva caminho registrado",()=>{var list=new List<WslDistribution>{new("Ubuntu","Registro",2,@"C:\distro")};WslInventory.Merge("  NAME                 STATE           VERSION\n* docker-desktop       Stopped         2\n  Ubuntu               Stopped         2\n",list);Assert(list.Count==2&&list.Single(d=>d.Name=="Ubuntu").BasePath==@"C:\distro"&&list.All(d=>d.State=="Stopped"));});
        Test("descoberta não segue junctions nem repete discos",()=>{string root=@"C:\fixture";var fs=new FakeFs(root);fs.Directory("disk");fs.Directory(@"disk\link",FileAttributes.ReparsePoint);fs.File(@"disk\a.vhdx",100);fs.File(@"disk\link\b.vhdx",200);var notes=new List<string>();var list=DockerDeepDiagnostic.FindDisks(fs,[(root+@"\disk","Docker"),(root+@"\disk","Docker")],notes,default);Assert(list.Count==1&&list[0].PhysicalBytes==100&&!fs.Visited.Contains(root+@"\disk\link")&&notes.Count>0);});
        Test("alocação desconhecida de disco fica inconclusiva",()=>{string root=@"C:\fixture";var fs=new FakeFs(root){UnknownAllocation=true};fs.Directory("disk");fs.File(@"disk\a.vhdx",100);var r=DockerDeepDiagnostic.FindDisks(fs,[(root+@"\disk","Docker")],[],default);Assert(r.Single().PhysicalBytes==null&&r[0].LogicalBytes==100);});
        Test("disco inacessível não causa total falso",()=>{string root=@"C:\fixture";var fs=new FakeFs(root);fs.Directory("disk");fs.Denied.Add(root+@"\disk");var notes=new List<string>();Assert(DockerDeepDiagnostic.FindDisks(fs,[(root+@"\disk","Docker")],notes,default).Count==0&&notes.Count>0);});
        Test("descoberta cancelável não percorre arquivos",()=>{string root=@"C:\fixture";var fs=new FakeFs(root);fs.Directory("disk");using var cts=new CancellationTokenSource();cts.Cancel();try{DockerDeepDiagnostic.FindDisks(fs,[(root+@"\disk","Docker")],[],cts.Token);throw new Exception("Não cancelou");}catch(OperationCanceledException){}Assert(fs.Visited.Count==0);});
        Test("alerta de espaço livre não executa operação",()=>{var p=new StorageAlertSettings(true,100*1024*1024,1024*1024,24);Assert(StorageAlertEvaluator.EvaluateFree(p,10).Single().Kind=="Espaço livre");Assert(StorageAlertEvaluator.EvaluateFree(p,200*1024*1024).Count==0);Assert(StorageAlertEvaluator.EvaluateFree(p,null).Single().Kind=="Inconclusivo");});
        Test("alertas desativados não emitem avisos",()=>{Assert(StorageAlertEvaluator.EvaluateHistory(Report(),new(false),0,DateTimeOffset.Now,"invalid").Count==0);});
        Test("alerta usa período completo e crescimento físico comparável",()=>{var r=Report(3L*1024*1024*1024);var now=DateTimeOffset.Now;var p=new StorageAlertSettings(true,1024*1024,1024*1024*1024,24);var a=StorageAlertEvaluator.EvaluateHistory(r,p,5L*1024*1024*1024,now,Sample(r,now.AddHours(-25),1024*1024*1024));Assert(a.Single().Kind=="Crescimento"&&a[0].ObservedHours==25);});
        Test("amostra recente não inventa crescimento de 24 horas",()=>{var r=Report(3L*1024*1024*1024);var now=DateTimeOffset.Now;var a=StorageAlertEvaluator.EvaluateHistory(r,new(),30L*1024*1024*1024,now,Sample(r,now.AddMinutes(-10),0));Assert(a.All(x=>x.Kind!="Crescimento"));});
        Test("amostra velha parcial ou escopo diferente não gera alerta",()=>{var r=Report(3L*1024*1024*1024);var now=DateTimeOffset.Now;foreach(var line in new[]{Sample(r,now.AddDays(-10),0),Sample(r,now.AddHours(-25),0,false),Sample(r,now.AddHours(-25),0).Replace(RecoveryHistory.GroupHash(r,r.Groups[0]),"other")})Assert(StorageAlertEvaluator.EvaluateHistory(r,new(),30L*1024*1024*1024,now,line).All(x=>x.Kind!="Crescimento"));r.Groups[0].Partial=true;Assert(StorageAlertEvaluator.EvaluateHistory(r,new(),30L*1024*1024*1024,now,Sample(r,now.AddHours(-25),0)).All(x=>x.Kind!="Crescimento"));});
        Test("ancestral junction impede descoberta",()=>{string root=@"C:\fixture";var fs=new FakeFs(root);fs.Directory("link",FileAttributes.ReparsePoint);fs.Directory(@"link\disk");fs.File(@"link\disk\a.vhdx",100);var notes=new List<string>();Assert(DockerDeepDiagnostic.FindDisks(fs,[(root+@"\link\disk","Docker")],notes,default).Count==0&&fs.Visited.Count==0&&notes.Count>0);});
        Test("disco ocupado é medido só por metadados e preservado",()=>{string root=Path.Combine(Environment.CurrentDirectory,"artifacts","m7-fixtures");Directory.CreateDirectory(root);string path=Path.Combine(root,"busy.vhdx");File.WriteAllBytes(path,new byte[4096]);using(var held=new FileStream(path,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){var r=DockerDeepDiagnostic.FindDisks(new WindowsFileSystem(),[(root,"Docker")],[],default);Assert(r.Single(d=>d.Path==path).LogicalBytes==4096);}Assert(File.Exists(path)&&new FileInfo(path).Length==4096);});
        Test("perfil de artefatos não libera fontes ou bancos",()=>{string root=@"C:\fixture";var fs=new FakeFs(root);fs.File("app.pdb",200);fs.File("data.db",300);fs.File("source.rs",100);var p=ArtifactMetadataProfiler.Inspect(fs,root,default);Assert(p.ExaminedFiles==3&&p.Extensions.Sum(e=>e.KnownPhysicalBytes)==600&&p.Largest.Where(f=>f.Path.EndsWith(".db")||f.Path.EndsWith(".rs")).All(f=>f.KnownProtected)&&p.Summary.Contains("E2.5"));});
        Test("perfil limitado não apresenta totais completos",()=>{string root=@"C:\fixture";var fs=new FakeFs(root);fs.File("a.bin",10);fs.File("b.bin",20);Assert(ArtifactMetadataProfiler.Inspect(fs,root,default,1).Partial);});
        Test("negação de acesso aninhada bloqueia tentativa de endpoint alternativo",()=>{Assert(DockerDeepDiagnostic.IsAccessDenied(new HttpRequestException("local",new IOException("pipe",new UnauthorizedAccessException()))));Assert(DockerDeepDiagnostic.IsAccessDenied(new System.ComponentModel.Win32Exception(5)));Assert(!DockerDeepDiagnostic.IsAccessDenied(new IOException("arquivo inexistente")));});
        Test("estado de cache ausente torna inventário explicitamente parcial",()=>{var r=Usage("{\"Images\":[],\"Volumes\":[],\"BuildCache\":[{\"ID\":\"a\",\"Size\":100,\"InUse\":false}]}");Assert(!r.InventoryComplete&&r.Resources.Single().Classification.Contains("inconclusivo")&&r.HostRecoverableConfirmedBytes==0);});
        Test("perfil exclui subescopo para não duplicar target",()=>{string root=@"C:\fixture";var fs=new FakeFs(root);fs.Directory("target");fs.File("source.rs",10);fs.File(@"target\a.rlib",100);var p=ArtifactMetadataProfiler.Inspect(fs,root,default,excluded:new HashSet<string>(StringComparer.OrdinalIgnoreCase){root+@"\target"});Assert(p.ExaminedFiles==1&&p.Extensions.Sum(e=>e.KnownPhysicalBytes)==10&&!fs.Visited.Contains(root+@"\target"));});
        Test("configuração inválida é rejeitada",()=>{foreach(var p in new[]{new StorageAlertSettings(PeriodHours:0),new StorageAlertSettings(GrowthBytes:0),new StorageAlertSettings(MinimumFreeBytes:-1)}){try{p.Validate();throw new Exception("Aceitou limite inválido");}catch(IOException){}}});
        Test("configuração persiste sem executar limpeza",()=>{string root=Path.Combine(Path.GetTempPath(),"Respiro.Missao7.Tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string path=Path.Combine(root,"alerts.json");var p=new StorageAlertSettings(false,20L<<30,1L<<30,12);p.Write(path);Assert(StorageAlertSettings.Read(path)==p);});
        Test("relatório excessivo não sobrescreve destino",()=>{string root=Path.Combine(Environment.CurrentDirectory,"artifacts","m7-fixtures");Directory.CreateDirectory(root);string path=Path.Combine(root,"report.json");File.WriteAllText(path,"preservado");var r=new DockerDeepReport();r.Notices.Add(new string('a',3*1024*1024));try{DockerDeepDiagnostic.Save(r,path);throw new Exception("Relatório ilimitado");}catch(IOException){}Assert(File.ReadAllText(path)=="preservado");});
    }
}